"""Legacy response-shape examples referenced by the development guide."""

from __future__ import annotations

from collections.abc import Iterable, Mapping
from typing import Any


def get_account_record(
    records: Iterable[Mapping[str, Any]], employee_id: str
) -> dict[str, Any] | None:
    """Return the complete matching legacy record."""

    for record in records:
        if record.get("employee_id") == employee_id:
            return dict(record)
    return None


def copy_sorted_records(records: Iterable[Mapping[str, Any]]) -> list[dict[str, Any]]:
    """Copy legacy records into the stable response order."""

    return sorted(
        (dict(record) for record in records),
        key=lambda record: (record["username"], record["employee_id"]),
    )


def list_accounts_by_department(
    records: Iterable[Mapping[str, Any]], department: str
) -> list[dict[str, Any]]:
    """Canonical collection adapter used by the portal."""

    return copy_sorted_records(
        record for record in records if record.get("department") == department
    )


def list_accounts_by_host_group(
    records: Iterable[Mapping[str, Any]], host_group: str
) -> list[dict[str, Any]]:
    """Canonical host-group collection adapter used by the portal."""

    return copy_sorted_records(
        record for record in records if record.get("host_group") == host_group
    )

from __future__ import annotations

import unittest

from account_service import (
    count_accounts_by_department,
    get_directory_account,
    list_accounts_by_department,
    list_accounts_by_host_group,
)


def employee_ids(records):
    return [record["employee_id"] for record in records]


class AccountServiceTests(unittest.TestCase):
    def test_existing_directory_lookup_returns_employee_record(self):
        account = get_directory_account("E001")
        self.assertEqual(account["username"], "alice")
        self.assertEqual(account["employee_id"], "E001")

    def test_lists_department_in_documented_order(self):
        self.assertEqual(
            employee_ids(list_accounts_by_department("Engineering")),
            ["E003", "E004"],
        )
        self.assertEqual(list_accounts_by_department("Missing"), [])

    def test_lists_host_group_in_documented_order(self):
        self.assertEqual(
            employee_ids(list_accounts_by_host_group("prod-web")),
            ["E002", "E003"],
        )
        self.assertEqual(list_accounts_by_host_group("missing"), [])

    def test_counts_departments(self):
        self.assertEqual(count_accounts_by_department("Finance"), 2)
        self.assertEqual(count_accounts_by_department("Engineering"), 2)
        self.assertEqual(count_accounts_by_department("Support"), 2)
        self.assertEqual(count_accounts_by_department("Missing"), 0)


if __name__ == "__main__":
    unittest.main()

